SELECT DATE_TRUNC('QUARTER', hire_date) AS quarter_start, manager_id, dept_id, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, COUNT_IF(level = 'L1') AS l1_events, ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN level = 'L1' THEN 1 END), 0), 2) AS salary_per_l1, SORT_ARRAY(COLLECT_SET(level)) AS level_list, AVG(salary) FILTER (WHERE level = 'L3') AS l3_avg_salary, COUNT(DISTINCT job_title) AS distinct_job_titles FROM employees GROUP BY quarter_start, manager_id, dept_id ORDER BY l1_events;
